import { InfisicalSDK } from "..";
import { AuthApi } from "../api/endpoints/auth";
import { UniversalAuthLoginRequest } from "../api/types";
import { MACHINE_IDENTITY_ID_ENV_NAME } from "./constants";
import { InfisicalSDKError, newInfisicalError } from "./errors";
import { getAwsRegion, performAwsIamLogin } from "./util";

type AuthenticatorFunction = (accessToken: string) => InfisicalSDK;

type AwsAuthLoginOptions = {
  identityId?: string;
};

export const renewToken = async (apiClient: AuthApi, token?: string) => {
  try {
    if (!token) {
      throw new InfisicalSDKError(
        "Unable to renew access token, no access token set."
      );
    }

    const res = await apiClient.renewToken({ accessToken: token });
    return res;
  } catch (err) {
    throw newInfisicalError(err);
  }
};

export default class AuthClient {
  constructor(
    private sdkAuthenticator: AuthenticatorFunction,
    private apiClient: AuthApi,
    private _accessToken?: string
  ) {}

  awsIamAuth = {
    login: async (options?: AwsAuthLoginOptions) => {
      try {
        const identityId =
          options?.identityId || process.env[MACHINE_IDENTITY_ID_ENV_NAME];
        if (!identityId) {
          throw new InfisicalSDKError(
            "Identity ID is required for AWS IAM authentication"
          );
        }

        const iamRequest = await performAwsIamLogin(await getAwsRegion());
        const res = await this.apiClient.awsIamAuthLogin({
          iamHttpRequestMethod: iamRequest.iamHttpRequestMethod,
          iamRequestBody: Buffer.from(iamRequest.iamRequestBody).toString(
            "base64"
          ),
          iamRequestHeaders: Buffer.from(
            JSON.stringify(iamRequest.iamRequestHeaders)
          ).toString("base64"),
          identityId,
        });

        return this.sdkAuthenticator(res.accessToken);
      } catch (err) {
        throw newInfisicalError(err);
      }
    },
    renew: async () => {
      try {
        const refreshedToken = await renewToken(
          this.apiClient,
          this._accessToken
        );
        return this.sdkAuthenticator(refreshedToken.accessToken);
      } catch (err) {
        throw newInfisicalError(err);
      }
    },
  };

  universalAuth = {
    login: async (options: UniversalAuthLoginRequest) => {
      try {
        const res = await this.apiClient.universalAuthLogin(options);
        return this.sdkAuthenticator(res.accessToken);
      } catch (err) {
        throw newInfisicalError(err);
      }
    },
    renew: async () => {
      try {
        const refreshedToken = await renewToken(
          this.apiClient,
          this._accessToken
        );
        return this.sdkAuthenticator(refreshedToken.accessToken);
      } catch (err) {
        throw newInfisicalError(err);
      }
    },
  };

  /**
  * Gets the current access token that is set on the SDK instance
  * @returns The current access token or null if no access token is set. `null` is returned if the SDK is not authenticated.
  */
  getAccessToken = () => this._accessToken || null;

  accessToken = (token: string) => {
    return this.sdkAuthenticator(token);
  };
}

export interface FetchHttpErrorResponse {
	/** Parsed JSON body when possible, otherwise the raw text. */
	data: unknown;
	status: number;
	config: {
		url: string;
		method: string;
	};
}

export class FetchHttpError extends Error {
	public readonly name = "FetchHttpError";
	public readonly response: FetchHttpErrorResponse;


	constructor(message: string, response: FetchHttpErrorResponse) {
		super(message);
		this.response = response;
	}
}

export const isFetchHttpError = (e: unknown): e is FetchHttpError =>
	e instanceof FetchHttpError;

import { FetchHttpError } from "./fetch-errors";
import { fetchWithRetry } from "./retry";

export type HttpMethod = "GET" | "POST" | "PATCH" | "DELETE" | "PUT" | "OPTIONS" | "HEAD";

export interface ApiClientConfig {
	baseURL: string;
	headers?: Record<string, string>;
	timeout?: number;
}

export interface RequestConfig {
	headers?: Record<string, string>;
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	params?: Record<string, any>;
	timeout?: number;
	/** data is used as the JSON body for DELETE requests. */
	data?: unknown;
}

const DEFAULT_TIMEOUT_MS = 10_000;
const JSON_CONTENT_TYPE = "application/json";
const FORM_URLENCODED_CONTENT_TYPE = "application/x-www-form-urlencoded";

/** @internal */
export const buildUrl = (
	baseURL: string,
	path: string,
	params?: RequestConfig["params"]
): string => {
	const relative = path.startsWith("/") ? path.slice(1) : path;
	if (!params) {
		return baseURL + relative;
	}
	const url = new URL(relative, baseURL);
	for (const [key, value] of Object.entries(params)) {
		if (value === undefined || value === null) continue;
		url.searchParams.append(key, String(value));
	}
	return url.toString();
};


/** @internal */
export const parseBody = async (response: Response): Promise<unknown> => {
	if (response.status === 204) return undefined;
	const text = await response.text();
	if (text.length === 0) return undefined;
	try {
		return JSON.parse(text);
	} catch {
		return text;
	}
};

/** @internal */
const encodeFormUrlencoded = (data: unknown, contentType: string): string => {
	if (typeof data === "string") {
		return data;
	}
	if (data instanceof URLSearchParams) {
		return data.toString();
	}
	if (typeof data === "object" && data !== null) {
		const params = new URLSearchParams();
		for (const [key, value] of Object.entries(
			data as Record<string, unknown>
		)) {
			if (value === undefined || value === null) continue;
			params.append(key, String(value));
		}
		return params.toString();
	}
	throw new TypeError(
		`ApiClient: Content-Type "${contentType}" requires a string, URLSearchParams, or plain object body, but received ${typeof data}.`
	);
};

export class ApiClient {
	private readonly baseURL: string;
	private readonly defaultHeaders: Record<string, string>;
	private readonly timeout: number;

	constructor(config: ApiClientConfig) {
		this.baseURL = config.baseURL.endsWith("/")
			? config.baseURL
			: `${config.baseURL}/`;
		this.defaultHeaders = { ...(config.headers ?? {}) };
		this.timeout = config.timeout ?? DEFAULT_TIMEOUT_MS;
	}

	public setAccessToken(token: string) {
		this.defaultHeaders["Authorization"] = `Bearer ${token}`;
	}

	public get<T>(url: string, config?: RequestConfig): Promise<T> {
		return this.request<T>("GET", url, undefined, config);
	}

	public post<T>(
		url: string,
		data?: unknown,
		config?: RequestConfig
	): Promise<T> {
		const { body, headers } = this.serializeBody(data, config);
		return this.request<T>("POST", url, body, {
			...config,
			headers,
		});
	}

	public put<T>(
		url: string,
		data?: unknown,
		config?: RequestConfig
	): Promise<T> {
		const { body, headers } = this.serializeBody(data, config);
		return this.request<T>("PUT", url, body, {
			...config,
			headers,
		});
	}

	public patch<T>(
		url: string,
		data?: unknown,
		config?: RequestConfig
	): Promise<T> {
		const { body, headers } = this.serializeBody(data, config);
		return this.request<T>("PATCH", url, body, {
			...config,
			headers,
		});
	}

	public delete<T>(url: string, config?: RequestConfig): Promise<T> {
		const { body, headers } = this.serializeBody(config?.data, config);
		return this.request<T>("DELETE", url, body, {
			...config,
			headers,
		});
	}

	private serializeBody(
		data: unknown,
		config?: RequestConfig
	): { body: string | undefined; headers: Record<string, string> } {
		const headers: Record<string, string> = { ...(config?.headers ?? {}) };

		if (data === undefined) {
			return { body: undefined, headers };
		}

		const contentType =
			headers["Content-Type"] ??
			this.defaultHeaders["Content-Type"] ??
			JSON_CONTENT_TYPE;

		headers["Content-Type"] = contentType;


		if (contentType === JSON_CONTENT_TYPE) {
			return { body: JSON.stringify(data), headers };
		}

		if (contentType === FORM_URLENCODED_CONTENT_TYPE) {
			return { body: encodeFormUrlencoded(data, contentType), headers };
		}

		if (typeof data !== "string") {
			throw new TypeError(
				`ApiClient: Content-Type "${contentType}" requires a pre-serialized string body, but received ${typeof data}. Serialize the data before passing it.`
			);
		}

		return { body: data, headers };

	}

	private async request<T>(
		method: HttpMethod,
		url: string,
		body: string | undefined,
		config?: RequestConfig
	): Promise<T> {
		const fullUrl = buildUrl(this.baseURL, url, config?.params);

		const headers: Record<string, string> = { ...this.defaultHeaders };
		if (config?.headers) {
			Object.assign(headers, config.headers);
		}

		const timeoutMs = config?.timeout ?? this.timeout;

		const doFetch = async (): Promise<Response> => {
			const controller = new AbortController();
			const timer = setTimeout(() => controller.abort(), timeoutMs);
			try {
				return await fetch(fullUrl, {
					method,
					headers,
					body,
					signal: controller.signal,
				});
			} finally {
				clearTimeout(timer);
			}
		};

		const response = await fetchWithRetry(doFetch);

		if (!response.ok) {
			throw new FetchHttpError(
				`Request failed with status ${response.status}`,
				{
					data: await parseBody(response),
					status: response.status,
					config: { url: fullUrl, method },
				}
			);
		}

		return (await parseBody(response)) as T;
	}
}

import { ApiClient } from "../base";
import { CreateEnvironmentRequest, CreateEnvironmentResponse } from "../types";

export class EnvironmentsApi {
  constructor(private apiClient: ApiClient) {}

  async create(
    data: CreateEnvironmentRequest
  ): Promise<CreateEnvironmentResponse> {
    return this.apiClient.post<CreateEnvironmentResponse>(
      `/api/v1/workspace/${data.projectId}/environments`,
      data
    );
  }
}

import { ApiClient } from "../base";
import {
  CreateDynamicSecretRequest,
  CreateDynamicSecretResponse,
  DeleteDynamicSecretRequest,
  DeleteDynamicSecretResponse,
  CreateLeaseRequest,
  CreateLeaseResponse,
  DeleteLeaseRequest,
  DeleteLeaseResponse,
  RenewLeaseRequest,
  RenewLeaseResponse,
} from "../types";

export class DynamicSecretsApi {
  constructor(private apiClient: ApiClient) {}

  async create(
    data: CreateDynamicSecretRequest
  ): Promise<CreateDynamicSecretResponse> {
    return this.apiClient.post<CreateDynamicSecretResponse>(
      "/api/v1/dynamic-secrets",
      data
    );
  }

  async delete(
    secretName: string,
    data: DeleteDynamicSecretRequest
  ): Promise<DeleteDynamicSecretResponse> {
    return this.apiClient.delete<DeleteDynamicSecretResponse>(
      `/api/v1/dynamic-secrets/${encodeURIComponent(secretName)}`,
      { data }
    );
  }

  leases = {
    create: async (data: CreateLeaseRequest): Promise<CreateLeaseResponse> => {
      return this.apiClient.post<CreateLeaseResponse>(
        "/api/v1/dynamic-secrets/leases",
        data
      );
    },

    delete: async (
      leaseId: string,
      data: DeleteLeaseRequest
    ): Promise<DeleteLeaseResponse> => {
      return this.apiClient.delete<DeleteLeaseResponse>(
        `/api/v1/dynamic-secrets/leases/${leaseId}`,
        { data }
      );
    },

    renew: async (
      leaseId: string,
      data: RenewLeaseRequest
    ): Promise<RenewLeaseResponse> => {
      return this.apiClient.post<RenewLeaseResponse>(
        `/api/v1/dynamic-secrets/leases/${leaseId}/renew`,
        data
      );
    },
  };
}

